export const seoReadySlugs = new Set<string>(
  Object.keys(articleRegistry).filter((key) => articleRegistry[key].seoReady)
);

/**
 * Checks if a specific converter pair has a complete, search-indexable article.
 * @param fromUnitId The ID of the source unit (e.g., 'meter')
 * @param toUnitId The ID of the target unit (e.g., 'kilometer')
 */
export function isSeoReady(fromUnitId: string, toUnitId: string): boolean {
  const slug = `${fromUnitId}-to-${toUnitId}`;
  return seoReadySlugs.has(slug);
}

